VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def roman_to_int(numeral):
    total = 0
    for index, letter in enumerate(numeral):
        value = VALUES[letter]
        if index + 1 < len(numeral) and VALUES[numeral[index + 1]] > value:
            total -= value
        else:
            total += value
    return total

def is_valid_ipv4(text):
    parts = text.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not all("0" <= char <= "9" for char in part):
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False
    return True

def flatten(items):
    flat = []
    for item in items:
        if isinstance(item, (list, tuple)):
            flat.extend(flatten(item))
        else:
            flat.append(item)
    return flat

from itertools import zip_longest


def compare_versions(a, b):
    left = [int(part) for part in a.split(".")]
    right = [int(part) for part in b.split(".")]
    for x, y in zip_longest(left, right, fillvalue=0):
        if x != y:
            return 1 if x > y else -1
    return 0
